param([string]$Output='public')
$ErrorActionPreference='Stop'
$root=if($PSScriptRoot){$PSScriptRoot}else{(Get-Location).Path}
$cfg=Get-Content (Join-Path $root 'site/config.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$data=Get-Content (Join-Path $root 'site/content.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$out=Join-Path $root $Output
$utf8=New-Object System.Text.UTF8Encoding($false)
function Write-Generated($path,$text){$full=Join-Path $out $path;[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($full))|Out-Null;[IO.File]::WriteAllText($full,$text,$utf8)}
function Esc($text){[System.Net.WebUtility]::HtmlEncode([string]$text)}
function Link($slug){$cfg.basePath+'/'+$slug}
function Url($slug){$cfg.url.TrimEnd('/')+$cfg.basePath+'/'+$slug}
function Json($value){ConvertTo-Json -InputObject $value -Depth 25 -Compress}
function ContactDetails{
 $phones=if($cfg.phones){@($cfg.phones)}elseif($cfg.phone){@($cfg.phone)}else{@()}
 $links=@($phones|ForEach-Object{"<a href='tel:$($_ -replace '[^+0-9]','')'>$(Esc $_)</a>"})
 $phoneText=if($links.Count){$links -join '; '}else{'[УКАЗАТЬ ДАННЫЕ]'}
 $emailText=if($cfg.email){"<a href='mailto:$(Esc $cfg.email)'>$(Esc $cfg.email)</a>"}else{'[УКАЗАТЬ ДАННЫЕ]'}
 $addressText=if($cfg.address){"<br>Адрес: <strong>$(Esc $cfg.address)</strong>"}else{''}
 $mapText=if($cfg.mapUrl){"<br><a href='$(Esc $cfg.mapUrl)' target='_blank' rel='noopener'>Ступино — Яндекс Карты</a>"}else{''}
 return "Телефон: $phoneText<br>Email: $emailText<br>Регион: $(Esc $cfg.region)$addressText$mapText"
}
function Video($id,$title){$t=Esc $title;return "<figure class='media'><a href='https://www.youtube.com/watch?v=$id' target='_blank' rel='noopener'><img src='https://i.ytimg.com/vi/$id/hqdefault.jpg' width='480' height='360' loading='lazy' alt='$t'></a><figcaption>$t · <a href='https://www.youtube.com/watch?v=$id'>Смотреть на YouTube</a></figcaption></figure>"}
function Faq($items){$html="<section class='faq' id='faq'><h2>Частые вопросы</h2>";foreach($i in $items){$html+="<details><summary>$(Esc $i.q)</summary><p>$(Esc $i.a)</p></details>"};return $html+'</section>'}
function Contact{ @"
<section class='band' id='contact'><div class='wrap contact-grid'><div><h2>Обсудить строительство</h2><p>Тип дома, участок и состав работ помогут подготовить запрос на расчет.</p><p>Телефон: $(if($cfg.phone){Esc $cfg.phone}else{'[УКАЗАТЬ ДАННЫЕ]'})<br>Email: $(if($cfg.email){Esc $cfg.email}else{'[УКАЗАТЬ ДАННЫЕ]'})<br>Регион: $(Esc $cfg.region)</p><a href='$(Esc $cfg.channel)'>YouTube-канал</a></div><form data-email='$(Esc $cfg.email)'><div class='form-grid'><label>Имя<input name='name' autocomplete='name' maxlength='100' required></label><label>Телефон или удобный способ связи<input name='contact' autocomplete='tel' maxlength='150' required></label><label>Тип дома<select name='type'><option>Барнхаус</option><option>Каркасный дом</option><option>Пока выбираю</option></select></label><label>Примерная площадь, м²<input name='area' type='number' min='1' max='5000' step='any'></label></div><label>Комментарий<textarea name='comment' rows='3' maxlength='3000'></textarea></label><label class='consent'><input type='checkbox' required name='consent'> <span>Согласен на обработку данных по <a href='$(Link 'consent/')'>условиям согласия</a></span></label><button class='btn' type='submit'>Подготовить запрос на расчет</button><output id='form-status' aria-live='polite'></output><pre id='request-preview' hidden></pre><a id='send-email' class='btn' hidden>Открыть почтовое приложение</a></form></div></section>
"@ }
function Objects{ $html="<div class='filters'><label>Тип дома<select id='type'><option value='all'>Все типы</option><option value='barnhaus'>Барнхаус</option><option value='karkas'>Каркасный дом</option></select></label><label>Этажность<select id='floors'><option value='all'>Все, включая неуказанные</option><option value='1'>Один этаж</option><option value='2'>Два этажа</option></select></label><label>Площадь<select id='area'><option value='all'>Любая, включая неуказанную</option><option value='small'>Менее 100 м²</option><option value='large'>От 100 м²</option></select></label></div><p id='result-count' role='status'>Найдено объектов: $($data.objects.Count)</p><div class='grid two'>";foreach($o in $data.objects){$objectImage=if($o.id -eq 'J3FnB9bFLVo'){"$(Link 'assets/barnhaus-8-9x13-5.jpg')"}else{"https://i.ytimg.com/vi/$($o.id)/hqdefault.jpg"};$html+="<article class='item' data-object data-type='$($o.type)' data-area='$($o.area)' data-floors='$($o.floors)'><a class='cover' href='https://www.youtube.com/watch?v=$($o.id)'><img src='$objectImage' width='480' height='360' loading='lazy' alt='$(Esc $o.name) — фото объекта на этапе строительства'></a><div class='copy'><h3>$(Esc $o.name)</h3><p>$(Esc $o.description)</p><p>Площадь: [УКАЗАТЬ ДАННЫЕ]<br>Этажность: [УКАЗАТЬ ДАННЫЕ]<br>Планировка и комплектация: [УКАЗАТЬ ДАННЫЕ]</p><a href='https://www.youtube.com/watch?v=$($o.id)'>Посмотреть этап строительства</a></div></article>"};return $html+"</div><p id='empty' class='empty' hidden>Нет объектов с подтвержденными характеристиками для выбранных фильтров.</p>" }
function Cards($items,$prefix){$html="<div class='grid'>";foreach($i in $items){$image='';if($i.slug -eq 'barnhaus' -and !$prefix){$image="<a class='card-photo' href='$(Link 'barnhaus/')'><img src='$(Link 'assets/barnhaus-8-9x13-5.jpg')' width='968' height='544' loading='lazy' alt='Каркасный барнхаус 8,9×13,5 на этапе строительства'></a>"}elseif($i.video){$image="<a class='card-photo' href='$(Link ($prefix+$i.slug+'/'))'><img src='https://i.ytimg.com/vi/$($i.video)/hqdefault.jpg' width='480' height='360' loading='lazy' alt='$(Esc $i.title) — кадр видео канала'></a>"};$html+="<article class='plain'>$image<h3><a href='$(Link ($prefix+$i.slug+'/'))'>$(Esc $i.title)</a></h3><p>$(Esc $i.intro)</p></article>"};return $html+'</div>'}
$script:urls=@()
function Page($slug,$title,$desc,$body,$faq=@(),$kind='WebPage',$videoId=''){
 $canonical=Url $slug;$rootLink=Link '';$og=Url ('assets/og/'+$(if($slug){$slug.TrimEnd('/').Replace('/','-')}else{'home'})+'.png')
 $schema=@(@{'@type'='Organization';'@id'=(Url '')+'#organization';name=$cfg.name;url=(Url '');sameAs=@($cfg.channel)},@{'@type'='WebSite';'@id'=(Url '')+'#website';name=$cfg.name;url=(Url '');inLanguage='ru-RU'},@{'@type'='WebPage';name=$title;description=$desc;url=$canonical;inLanguage='ru-RU';isPartOf=@{'@id'=(Url '')+'#website'}},@{'@type'='ImageObject';contentUrl=$og;caption=$title;width=1200;height=630})
 $crumb='';if($slug){$crumb="<div class='wrap breadcrumbs'><a href='$rootLink'>Главная</a><span>/</span><span>$(Esc $title)</span></div>";$schema+=@{'@type'='BreadcrumbList';itemListElement=@(@{'@type'='ListItem';position=1;name='Главная';item=(Url '')},@{'@type'='ListItem';position=2;name=$title;item=$canonical})}}
 if($kind -eq 'Article'){$schema+=@{'@type'='Article';headline=$title;description=$desc;url=$canonical;image=$og;inLanguage='ru-RU';articleBody=([regex]::Replace($body,'<[^>]+>',' ') -replace '\s+',' ').Trim()}}
 if($kind -eq 'Service'){$schema+=@{'@type'='Service';name=$title;description=$desc;url=$canonical}}
 if($faq.Count){$questions=@();foreach($f in $faq){$questions+=@{'@type'='Question';name=$f.q;acceptedAnswer=@{'@type'='Answer';text=$f.a}}};$schema+=@{'@type'='FAQPage';mainEntity=$questions}}
 if($cfg.email){$schema[0].email=$cfg.email}
 if($cfg.phones){$schema[0].telephone=@($cfg.phones)}elseif($cfg.phone){$schema[0].telephone=$cfg.phone}
 if($cfg.address){$schema[0].address=@{'@type'='PostalAddress';addressLocality='Ступино';addressRegion='Московская область';addressCountry='RU'}}
 $json=Json @{'@context'='https://schema.org';'@graph'=$schema}
 $articleMeta=if($kind -eq 'Article'){"<meta property='og:type' content='article'>"}else{"<meta property='og:type' content='website'>"}
 $html=@"
<!doctype html><html lang='ru'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>$(Esc $title) | $(Esc $cfg.name)</title><meta name='description' content='$(Esc $desc)'><link rel='canonical' href='$canonical'><meta name='theme-color' content='#294f3d'><meta property='og:title' content='$(Esc $title)'><meta property='og:description' content='$(Esc $desc)'>$articleMeta<meta property='og:url' content='$canonical'><meta property='og:image' content='$og'><meta property='og:image:width' content='1200'><meta property='og:image:height' content='630'><meta property='og:site_name' content='$(Esc $cfg.name)'><meta property='og:locale' content='ru_RU'><meta name='twitter:card' content='summary_large_image'><meta name='twitter:title' content='$(Esc $title)'><meta name='twitter:description' content='$(Esc $desc)'><meta name='twitter:image' content='$og'><link rel='stylesheet' href='$(Link 'assets/styles.css')'><script src='$(Link 'assets/app.js')' defer></script><script type='application/ld+json'>$json</script></head><body><a class='skip btn' href='#main'>К содержанию</a><header><div class='wrap header-inner'><a class='brand' href='$rootLink'>$(Esc $cfg.name)<small>Каркасные дома · Барнхаусы</small></a><button class='menu' aria-label='Меню' aria-expanded='false' aria-controls='navigation'><svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' aria-hidden='true'><path d='M4 6h16M4 12h16M4 18h16'/></svg></button><nav id='navigation' aria-label='Основная навигация'><a href='$(Link 'barnhaus/')'>Барнхаусы</a><a href='$(Link 'karkasnye-doma/')'>Каркасные дома</a><a href='$(Link 'proekty-domov/')'>Объекты</a><a href='$(Link 'ceny/')'>Стоимость</a><a href='$(Link 'blog/')'>Блог</a><a href='#contact'>Консультация</a></nav></div></header>$crumb<main id='main'>$body$(Contact)</main><footer><div class='wrap grid'><div><h3>$(Esc $cfg.name)</h3><p>Материалы о каркасном строительстве и барнхаусах.</p><p>Регион: $(Esc $cfg.region)<br>Телефон: [УКАЗАТЬ ДАННЫЕ]<br>Email: [УКАЗАТЬ ДАННЫЕ]<br>Мессенджеры и соцсети: [УКАЗАТЬ ДАННЫЕ]<br>Реквизиты: [УКАЗАТЬ ДАННЫЕ]</p><a href='$(Esc $cfg.channel)'>YouTube</a></div><div><h3>Строительство</h3><ul>$(($data.services | ForEach-Object {"<li><a href='$(Link ($_.slug+'/'))'>$(Esc $_.title)</a></li>"}) -join '')</ul></div><div><h3>Полезное</h3><ul><li><a href='$(Link 'blog/')'>Все статьи</a></li><li><a href='$(Link 'proekty-domov/')'>Объекты и видео</a></li><li><a href='#faq'>Вопросы и ответы</a></li></ul></div><div><h3>Документы</h3><ul><li><a href='$(Link 'privacy/')'>Политика конфиденциальности</a></li><li><a href='$(Link 'consent/')'>Согласие на обработку данных</a></li></ul><p>Цены, сроки и комплектации требуют подтверждения. Название использовано по YouTube-каналу.</p></div></div></footer></body></html>
"@
 $oldContacts="Телефон: $(if($cfg.phone){Esc $cfg.phone}else{'[УКАЗАТЬ ДАННЫЕ]'})<br>Email: $(if($cfg.email){Esc $cfg.email}else{'[УКАЗАТЬ ДАННЫЕ]'})<br>Регион: $(Esc $cfg.region)"
 $oldFooter="Регион: $(Esc $cfg.region)<br>Телефон: $(if($cfg.phone){Esc $cfg.phone}else{'[УКАЗАТЬ ДАННЫЕ]'})<br>Email: $(if($cfg.email){Esc $cfg.email}else{'[УКАЗАТЬ ДАННЫЕ]'})"
 $html=$html.Replace($oldContacts,(ContactDetails)).Replace($oldFooter,(ContactDetails))
 $html=$html.Replace("Регион: $(Esc $cfg.region)<br>Телефон: [УКАЗАТЬ ДАННЫЕ]<br>Email: [УКАЗАТЬ ДАННЫЕ]",(ContactDetails))
 $html=$html.Replace('<body>',"<body><div class='topline'><div class='wrap'><span>Каркасные дома · Барнхаусы</span><a href='$(Esc $cfg.channel)'>Работы и разборы на YouTube</a></div></div>")
  $html=$html.Replace("<meta name='theme-color' content='#294f3d'>","<meta name='theme-color' content='#ffd21f'>")
  $headerContact="<div class='header-contact'><a href='tel:$($cfg.phone -replace '[^+0-9]','')'>$(Esc $cfg.phone)</a><a href='#contact'>Обсудить проект →</a></div>"
  $html=$html.Replace("</nav></div></header>","</nav>$headerContact</div></header>")
  $html=$html.Replace("<label>Комментарий<textarea", "<label>Ссылка на проект<input name='project' type='url' placeholder='https://' maxlength='1000'></label><label>Комментарий<textarea")
  $html=$html.Replace("<button class='btn' type='submit'>", "<input type='hidden' name='selection'><button class='btn' type='submit'>")
  $html=$html.Replace("</body>","<dialog id='photo-dialog' aria-label='Просмотр фотографии'><button type='button' class='dialog-close' title='Закрыть' aria-label='Закрыть'>×</button><img alt=''><p></p></dialog><dialog id='compare-dialog' aria-labelledby='compare-title'><button type='button' class='dialog-close' title='Закрыть' aria-label='Закрыть'>×</button><h2 id='compare-title'>Сравнение объектов</h2><div id='compare-content'></div></dialog><div class='quick-contact'><a href='tel:$($cfg.phone -replace '[^+0-9]','')' aria-label='Позвонить'>Позвонить</a><a href='#contact'>Запросить смету →</a></div></body>")
  Write-Generated $(if($slug){$slug+'index.html'}else{'index.html'}) $html
 $script:urls+=$canonical
 # Generate an independent 1200x630 social image for every page.
 $bitmap=New-Object Drawing.Bitmap -ArgumentList 1200,630;$g=[Drawing.Graphics]::FromImage($bitmap);$g.Clear([Drawing.Color]::FromArgb(232,238,233));$brush=New-Object Drawing.SolidBrush -ArgumentList ([Drawing.Color]::FromArgb(41,79,61));$g.FillRectangle($brush,0,0,24,630);$font1=New-Object Drawing.Font -ArgumentList 'Arial',24;$font2=New-Object Drawing.Font -ArgumentList 'Arial',42,([Drawing.FontStyle]::Bold);$font3=New-Object Drawing.Font -ArgumentList 'Arial',20;$rect=New-Object Drawing.RectangleF -ArgumentList 60,180,1080,300;$g.DrawString($cfg.name,$font1,[Drawing.Brushes]::DarkSlateGray,60,60);$g.DrawString($title,$font2,[Drawing.Brushes]::Black,$rect);$g.DrawString('Каркасные дома / Барнхаусы / Этапы строительства',$font3,[Drawing.Brushes]::DarkSlateGray,60,540);$imagePath=Join-Path $out ('assets/og/'+$(if($slug){$slug.TrimEnd('/').Replace('/','-')}else{'home'})+'.png');[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($imagePath))|Out-Null;$bitmap.Save($imagePath,[Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$bitmap.Dispose()
}
Add-Type -AssemblyName System.Drawing
$requestHint=if($cfg.email){'Подготовьте проект, сведения об участке и перечень работ. Форма составит письмо для самостоятельной отправки через почтовое приложение.'}else{'Подготовьте проект, сведения об участке и перечень работ. Получатель заявки пока требует подключения.'}
