$faq[0].a='Подтвержденного прайса нет. '+$requestHint
$landing=@"
<section class='hero'><img src='https://i.ytimg.com/vi/J3FnB9bFLVo/hqdefault.jpg' width='480' height='360' fetchpriority='high' alt='Сборка стен барнхауса 8,9×13,5 — кадр видео канала'><div class='wrap'><div class='eyebrow'>Всё правильно, всё сходится!</div><h1>Строительство каркасных домов и барнхаусов</h1><p>От платформы до фасада. Реальные этапы, материалы и узлы из видео канала — для осознанного выбора будущего дома.</p><div class='actions'><a class='btn light' href='#contact'>Рассчитать стоимость</a><a class='btn light' href='$(Link 'proekty-domov/')'>Посмотреть проекты</a></div></div></section><section><div class='wrap'><h2>Сначала разберемся в деталях</h2><div class='grid'><div class='plain'><h3>Работы на видео</h3><p>Сборка стен, утепление платформы, мембрана и фасад доступны в сериях канала.</p></div><div class='plain'><h3>Материалы и узлы</h3><p>В названиях роликов встречаются ОСП, сайдинг Grand Line и профлист Stinergy СТ15.</p></div><div class='plain'><h3>Расчет по задаче</h3><p>Площадь и перечень работ обсуждаются вместе. Подтвержденный прайс: [УКАЗАТЬ ДАННЫЕ].</p></div></div></div></section><section class='band'><div class='wrap'><h2>Направления строительства</h2>$(Cards ($data.services | Select-Object -First 7) '')</div></section><section><div class='wrap'><h2>Объекты из серий канала</h2>$(Objects)</div></section><section class='band'><div class='wrap'><h2>Этапы: что можно изучить на канале</h2><ol class='steps'><li>Обвязка, лаги и платформа</li><li>Сборка стен и перегородок</li><li>Балка и стропила</li><li>Мембрана, обрешетка и фасад</li></ol><a href='$(Link 'stroitelstvo-doma/')'>Обсудить состав работ</a></div></section><section><div class='wrap'><h2>Видео с объектов</h2><div class='grid'>$(($data.videos|ForEach-Object{Video $_.id $_.title}) -join '')</div></div></section><section class='band'><div class='wrap'><h2>Что влияет на расчет</h2><p>Проект, участок, комплект материалов, доставка и объем работ. Цену без подтвержденной сметы не указываем.</p><a class='btn' href='$(Link 'ceny/')'>Посмотреть комплектации</a></div></section><section><div class='wrap'><h2>Читайте также</h2>$(Cards ($data.articles|Select-Object -First 3) 'blog/')$(Faq $faq)</div></section>
"@
$landing=$landing.Replace('От платформы до фасада. Реальные этапы, материалы и узлы из видео канала — для осознанного выбора будущего дома.','От платформы до фасада — реальные этапы строительства, материалы и узлы, чтобы вы осознанно выбирали будущий дом.')
$landing=$landing.Replace('https://i.ytimg.com/vi/J3FnB9bFLVo/hqdefault.jpg',"$(Link 'assets/barnhaus-8-9x13-5.jpg')")
$landing=$landing.Replace('Сборка стен барнхауса 8,9×13,5 — кадр видео канала','Барнхаус 8,9×13,5 на этапе строительства')
$selection=(Get-Content (Join-Path $root 'site/selection.html') -Raw -Encoding UTF8).Replace('{{BASE}}', (Link ''))
$landing=$landing.Replace("<section><div class='wrap'><h2>Сначала разберемся в деталях</h2>", $selection+"<section><div class='wrap'><h2>Сначала разберемся в деталях</h2>")
$gallery="<section class='visual-strip'><div class='wrap'><div class='visual-grid'><figure><img src='$(Link 'assets/frame.jpg')' width='480' height='360' loading='lazy' alt='Сборка стен барнхауса на объекте'><figcaption>Каркас и стены</figcaption></figure><figure><img src='$(Link 'assets/roof.jpg')' width='480' height='360' loading='lazy' alt='Балка и стропила барнхауса'><figcaption>Кровля и стропила</figcaption></figure><figure><img src='$(Link 'assets/facade.jpg')' width='480' height='360' loading='lazy' alt='Обрешетка и профлист на фасаде'><figcaption>Фасад и обрешетка</figcaption></figure></div></div></section>"
$landing=$landing.Replace("<section><div class='wrap'><h2>Сначала разберемся в деталях</h2>",$gallery+"<section><div class='wrap'><h2>Сначала разберемся в деталях</h2>")
Page '' 'Строительство каркасных домов и барнхаусов' 'Реальные этапы строительства барнхаусов и каркасных домов: видео, материалы, вопросы к смете и запрос на расчет.' $landing $faq
foreach($s in $data.services){
 $desc=$s.intro;$body="<section class='page-head'><div class='wrap'><h1>$(Esc $s.title)</h1><p class='lead'>$(Esc $s.intro)</p><div class='actions'><a class='btn' href='#contact'>Получить консультацию</a><a class='btn secondary' href='$(Link 'proekty-domov/')'>Подобрать проект</a></div></div></section><section class='band'><div class='wrap'><h2>Что обсудить перед выбором</h2><p>$(Esc $s.focus)</p><h3>Комплектации и состав работ</h3><div class='table-scroll'><table><thead><tr><th>Этап расчета</th><th>Что уточнить</th><th>Предложение компании</th></tr></thead><tbody><tr><td>Конструкции</td><td>Основание, каркас, кровля</td><td>[УКАЗАТЬ ДАННЫЕ]</td></tr><tr><td>Теплый контур</td><td>Утепление, мембраны, окна, двери</td><td>[УКАЗАТЬ ДАННЫЕ]</td></tr><tr><td>Под ключ</td><td>Инженерия, отделка и исключения</td><td>[УКАЗАТЬ ДАННЫЕ]</td></tr></tbody></table></div><p>Эта таблица — перечень для обсуждения, а не утвержденные комплектации компании.</p></div></section><section><div class='wrap'><h2>Этапы, сроки и стоимость</h2><ol class='steps'><li>Подготовить задание и сведения об участке</li><li>Уточнить проект, состав материалов и работ</li><li>Запросить смету, график и порядок приемки</li><li>Согласовать условия договора</li></ol><p>Сроки и стоимость по выбранному проекту: [УКАЗАТЬ ДАННЫЕ].</p><h2>Реальные этапы на видео</h2>$(Video $s.video $s.title)<h2>Связанные объекты</h2>$(Objects)$(Faq $faq)<h2>Читайте также</h2>$(Cards ($data.articles|Where-Object{$_.service -eq $s.slug}) 'blog/')<div class='longlinks'><a href='$(Link 'ceny/')'>Стоимость и состав расчета</a><a href='$(Link 'individualnyj-proekt/')'>Индивидуальное задание</a><a href='$(Link 'blog/')'>Блог о строительстве</a></div></div></section>";
  $photo="<figure class='house-banner'><img src='$(Link 'assets/timber-house.jpg')' width='3224' height='2304' loading='lazy' alt='Готовый каркасный дом в Верхней Савойе, Франция'><figcaption>Иллюстрация каркасного дома. © Yann Forget / <a href='https://commons.wikimedia.org/wiki/File:Timber-framed_villa,_Haute-Savoie,_France.jpg'>Wikimedia Commons</a> / <a href='https://creativecommons.org/licenses/by-sa/4.0/'>CC BY-SA 4.0</a>. Отображение адаптировано по размеру.</figcaption></figure><p><a class='btn secondary' href='https://www.youtube.com/watch?v=$($s.video)'>Смотреть этап строительства на YouTube</a></p>"
  $body=$body.Replace((Video $s.video $s.title),$photo)
  Page ($s.slug+'/') $s.title $desc $body $faq 'Service'
}
foreach($a in $data.articles){
 $afaq=@(@{q='Подтверждает ли видео параметры моего дома?';a='Нет. Видео относится к конкретному этапу объекта канала. Параметры вашего дома нужно согласовать в проекте и документах.'},@{q='Какие данные нужны для консультации?';a=$a.check.Replace('|',', ')+'.'})
 $rows='';$items='';foreach($checkItem in $a.check.Split('|')){$safe=Esc $checkItem;$rows+="<tr><td>$safe</td><td>Запросить документ или пояснение по вашему проекту</td></tr>";$items+="<li>$safe</li>"}
 $related=$data.articles|Where-Object{$_.slug -ne $a.slug}|Select-Object -First 2;$body="<div class='wrap article'><section class='page-head'><h1>$(Esc $a.title)</h1><p class='lead'>$(Esc $a.intro)</p><p class='note'>Материал основан на названиях и темах видео канала. Даты публикации и обновления материала: [УКАЗАТЬ ДАННЫЕ].</p><div class='toc'><b>Содержание</b><ol><li><a href='#topic'>$(Esc $a.heading)</a></li><li><a href='#check'>Что уточнить</a></li><li><a href='#video'>Видео по теме</a></li><li><a href='#faq'>Вопросы и ответы</a></li></ol></div></section><section id='topic'><h2>$(Esc $a.heading)</h2><p>$(Esc $a.body)</p><h3>Исходные данные</h3><ul>$items</ul></section><section id='check'><h2>Что уточнить по своему проекту</h2><div class='table-scroll'><table><thead><tr><th>Вопрос</th><th>Следующий шаг</th></tr></thead><tbody>$rows</tbody></table></div></section><section id='video'><h2>Видео по теме</h2>$(Video $a.video $a.heading)<p>Источник: <a href='https://www.youtube.com/watch?v=$($a.video)'>ролик YouTube-канала</a>. Числовые параметры, не подтвержденные источником, не добавлены.</p><a class='btn' href='$(Link ($a.service+'/'))'>Обсудить проект и расчет</a></section>$(Faq $afaq)<section><h2>Читайте также</h2>$(Cards $related 'blog/')</section></div>"
 Page ('blog/'+$a.slug+'/') $a.title $a.intro $body $afaq 'Article'
}
Page 'blog/' 'Блог о каркасных домах и барнхаусах' 'Материалы по темам YouTube-канала: проект, утепление, фасад, этапы строительства и вопросы к расчету.' "<section><div class='wrap'><h1>Блог о строительстве</h1><p>Видео, проверяемые вопросы и материалы для выбора дома.</p>$(Cards $data.articles 'blog/')$(Faq $faq)</div></section>" $faq
foreach($legal in @('privacy','consent')){$title=if($legal -eq 'privacy'){'Политика конфиденциальности'}else{'Согласие на обработку данных'};Page ($legal+'/') $title 'Сведения о работе формы и полях, требующих заполнения владельцем сайта.' "<section><div class='wrap article'><h1>$title</h1><p>Оператор персональных данных, реквизиты, контакт для обращений: [УКАЗАТЬ ДАННЫЕ].</p><p>Текущая форма составляет текст в браузере. Без подключенного email или CRM запрос не отправляется. Данные формы не сохраняются в localStorage.</p><p>Цель будущей обработки: ответ на запрос о строительстве. Перечень данных: имя, контакт, тип дома, площадь и комментарий. Получатели, сроки хранения, порядок отзыва согласия и окончательная редакция документа: [УКАЗАТЬ ДАННЫЕ].</p><p>Фотографии-превью загружаются с YouTube. Информация о запросах к хостингу и внешним ресурсам описывается их владельцами.</p>$(Faq $faq)</div></section>" $faq}
