Write-Generated 'assets/app.js' (Get-Content (Join-Path $root 'site/app.js') -Raw -Encoding UTF8)
foreach($asset in @('banner.jpg','frame.jpg','roof.jpg','facade.jpg','channel-cover.jpg','construction-cc0.jpg','timber-house.jpg','barnhaus-8-9x13-5.jpg')){[IO.File]::Copy((Join-Path $root "site/assets/$asset"),(Join-Path $out "assets/$asset"),$true)}
